/* Superhuman DNA — deep violet-tinted dark, refined gradients, glowing accents, keyboard-first */
.theme-superhuman-dna {
  --bg: oklch(0.974 0.030 88.4);
  --surface: oklch(0.994 0.008 91.5);
  --surface-2: oklch(0.977 0.040 96.2);
  --fg: oklch(0.286 0.058 9.5);
  --fg-muted: oklch(0.558 0.042 6.0);
  --accent: oklch(0.286 0.058 9.5);
  --accent-fg: oklch(0.974 0.030 88.4);
  --accent-2: oklch(0.859 0.078 295.4);
  --line: oklch(0.8 0.08 300 / 16%);
  --success: oklch(0.532 0.096 180.6);
  --warning: oklch(0.8 0.15 80);
  --danger: oklch(0.537 0.215 19.2);

  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.3 0.05 10 / 12%), inset 0 1px 0 oklch(1 0 0 / 60%);
  --shadow-2: 0 10px 30px -12px oklch(0.3 0.05 10 / 22%), inset 0 1px 0 oklch(1 0 0 / 65%);
  --shadow-3: 0 30px 70px -24px oklch(0.4 0.2 300 / 28%), inset 0 1px 0 oklch(1 0 0 / 70%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 55%, transparent),
    0 0 24px -4px color-mix(in oklab, var(--accent) 55%, transparent);

  --border-width: 1px;
  --blur-amount: 8px;

  --font-display: "Instrument Serif", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.04em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  background-image:
    radial-gradient(100% 60% at 15% 0%, oklch(0.4 0.18 305 / 30%) 0%, transparent 60%),
    radial-gradient(80% 50% at 90% 10%, oklch(0.4 0.16 245 / 24%) 0%, transparent 60%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-superhuman-dna h1,
.theme-superhuman-dna h2,
.theme-superhuman-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

.theme-superhuman-dna kbd,
.theme-superhuman-dna code {
  font-family: var(--font-mono);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: oklch(1 0 0 / 6%);
  padding: 0.05em 0.4em;
  font-size: 0.85em;
}

/* signature */
.theme-superhuman-dna { --font-app: var(--font-body); }

.theme-superhuman-dna h1 { font-style: italic; font-weight: 400; }
.theme-superhuman-dna { background-image: linear-gradient(180deg, oklch(1 0.02 90 / 60%), transparent 400px); }
.theme-superhuman-dna button { letter-spacing: 0.02em; }
.theme-superhuman-dna h1 { font-size: clamp(3rem, 6vw, 5rem) !important; }
.theme-superhuman-dna button:hover { box-shadow: 0 0 24px color-mix(in oklab, #d4c7ff 60%, transparent); }

/* depth */
.theme-superhuman-dna kbd { text-transform: uppercase; font-size: 0.72em; letter-spacing: 0.06em; background: var(--surface); border-bottom-width: 2px; border-bottom-color: color-mix(in oklab, var(--fg) 25%, var(--line)); box-shadow: 0 1px 0 oklch(0.3 0.05 10 / 15%); }
.theme-superhuman-dna thead th { text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.68rem; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); }
.theme-superhuman-dna td { border-bottom: 1px solid color-mix(in oklab, var(--line) 50%, transparent); }
.theme-superhuman-dna tbody tr:hover { background: color-mix(in oklab, var(--accent-2) 20%, transparent); box-shadow: inset 3px 0 0 var(--accent); }
.theme-superhuman-dna a { color: var(--fg); text-decoration: underline; text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; text-underline-offset: 3px; }
.theme-superhuman-dna a:hover { text-decoration-color: var(--accent); }
.theme-superhuman-dna input, .theme-superhuman-dna select, .theme-superhuman-dna textarea { border: 1px solid var(--line); background: var(--surface); transition: box-shadow 140ms ease, border-color 140ms ease; }
.theme-superhuman-dna input:focus-visible, .theme-superhuman-dna select:focus-visible, .theme-superhuman-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-superhuman-dna ::selection { background: color-mix(in oklab, var(--accent-2) 55%, transparent); }
.theme-superhuman-dna ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-superhuman-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-superhuman-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 35%, transparent); border-radius: var(--radius-pill); }
.theme-superhuman-dna button:active { transform: translateY(1px); }
.theme-superhuman-dna .label-caps { font-size: 0.68rem; color: var(--fg-muted); }

/* alt mode: night mode — the original Superhuman deep-violet cockpit */
.theme-superhuman-dna.alt-mode {
  --bg: oklch(0.185 0.045 295);
  --surface: oklch(0.225 0.050 295);
  --surface-2: oklch(0.270 0.055 295);
  --fg: oklch(0.950 0.015 300);
  --fg-muted: oklch(0.700 0.030 300);
  --line: oklch(0.85 0.08 300 / 18%);
  --accent: oklch(0.780 0.110 300);
  --accent-fg: oklch(0.160 0.040 295);
  --accent-2: oklch(0.550 0.180 300);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 55%), inset 0 1px 0 oklch(1 0 0 / 5%);
  --shadow-2: 0 10px 30px -12px oklch(0 0 0 / 70%), inset 0 1px 0 oklch(1 0 0 / 6%);
  --shadow-3: 0 30px 70px -24px oklch(0.4 0.2 300 / 45%), inset 0 1px 0 oklch(1 0 0 / 8%);
  background-image:
    radial-gradient(100% 60% at 15% 0%, oklch(0.4 0.18 305 / 45%) 0%, transparent 60%),
    radial-gradient(80% 50% at 90% 10%, oklch(0.4 0.16 245 / 35%) 0%, transparent 60%);
  background-attachment: fixed;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
